describe('HTTP Status Codes Verification', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/status_codes');
  });

  it('should navigate to 200 status code page and verify response message', () => {
    cy.contains('a', '200').click();
    cy.url().should('include', '/status_codes/200');
    cy.get('body').should('contain', 'This page returned a 200 status code');
  });

  it('should navigate to 404 status code page and verify response message', () => {
    cy.contains('a', '404').click();
    cy.url().should('include', '/status_codes/404');
    cy.get('body').should('contain', 'This page returned a 404 status code');
  });

  it('should return to status codes page and verify navigation between different status codes', () => {
    cy.contains('a', '200').click();
    cy.url().should('include', '/status_codes/200');
    cy.get('body').should('contain', 'This page returned a 200 status code');

    cy.visit('https://the-internet.herokuapp.com/status_codes');
    cy.url().should('include', '/status_codes');

    cy.contains('a', '404').click();
    cy.url().should('include', '/status_codes/404');
    cy.get('body').should('contain', 'This page returned a 404 status code');
  });

  it('should verify 500 status code page displays correct message', () => {
    cy.contains('a', '500').click();
    cy.url().should('include', '/status_codes/500');
    cy.get('body').should('contain', 'This page returned a 500 status code');
  });

  it('should handle rapid navigation between different status code pages', () => {
    cy.contains('a', '200').click();
    cy.url().should('include', '/status_codes/200');

    cy.visit('https://the-internet.herokuapp.com/status_codes');
    cy.contains('a', '301').click();
    cy.url().should('include', '/status_codes/301');
    cy.get('body').should('contain', 'This page returned a 301 status code');

    cy.visit('https://the-internet.herokuapp.com/status_codes');
    cy.contains('a', '404').click();
    cy.url().should('include', '/status_codes/404');
    cy.get('body').should('contain', 'This page returned a 404 status code');
  });
});
